package com.selectivesmoothing;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup(SelectiveSmoothingConfig.GROUP)
public interface SelectiveSmoothingConfig extends Config
{
	String GROUP = "selectiveanimationsmoothing";

	@ConfigItem(
		keyName = "smoothLocalPlayer",
		name = "Smooth your player",
		description = "Smooth your own character's animations (walking, running, attacking, skilling)",
		position = 1
	)
	default boolean smoothLocalPlayer()
	{
		return false;
	}

	@ConfigItem(
		keyName = "smoothOtherPlayers",
		name = "Smooth other players",
		description = "Smooth other players' animations",
		position = 2
	)
	default boolean smoothOtherPlayers()
	{
		return false;
	}
}

