package com.selectivesmoothing;

import com.google.inject.Provides;
import java.util.HashSet;
import java.util.Set;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Player;
import net.runelite.api.events.AnimationChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.PlayerChanged;
import net.runelite.api.events.PlayerSpawned;
import net.runelite.api.gameval.AnimationID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;

/**
 * Smooths (interpolates) animations for NPCs, bosses and objects, but not for players.
 * <p>
 * The client's interpolation filter only receives an animation ID, not the actor playing it,
 * so this plugin learns which animation IDs players use (attacks, skilling, walk/run/idle poses)
 * and refuses to smooth those. Everything else, such as boss attacks and specials, is smoothed.
 */
@Slf4j
@PluginDescriptor(
	name = "Selective Animation Smoothing",
	description = "Animation smoothing for NPCs, bosses and objects, but not for players",
	tags = {"animation", "smoothing", "interpolation", "npcs", "bosses", "raids"},
	conflicts = "Animation Smoothing"
)
public class SelectiveSmoothingPlugin extends Plugin
{
	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private SelectiveSmoothingConfig config;

	/** Animation IDs seen on your own character. */
	private final Set<Integer> localPlayerAnims = new HashSet<>();
	/** Animation IDs seen on other players. */
	private final Set<Integer> otherPlayerAnims = new HashSet<>();

	private boolean smoothLocal;
	private boolean smoothOthers;

	@Provides
	SelectiveSmoothingConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SelectiveSmoothingConfig.class);
	}

	@Override
	protected void startUp()
	{
		readConfig();
		clientThread.invokeLater(() ->
		{
			if (client.getTopLevelWorldView() == null)
			{
				return;
			}
			for (Player player : client.getTopLevelWorldView().players())
			{
				learn(player);
			}
		});
		client.setAnimationInterpolationFilter(this::shouldSmooth);
	}

	@Override
	protected void shutDown()
	{
		client.setAnimationInterpolationFilter(null);
		localPlayerAnims.clear();
		otherPlayerAnims.clear();
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (SelectiveSmoothingConfig.GROUP.equals(event.getGroup()))
		{
			readConfig();
		}
	}

	/** A player started an attack, skilling action, emote, etc. */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		if (event.getActor() instanceof Player)
		{
			learn((Player) event.getActor());
		}
	}

	/** A player came into view: learn their walk/run/idle poses. */
	@Subscribe
	public void onPlayerSpawned(PlayerSpawned event)
	{
		learn(event.getPlayer());
	}

	/** A player's appearance changed, e.g. a weapon swap changes their walk/run/idle poses. */
	@Subscribe
	public void onPlayerChanged(PlayerChanged event)
	{
		learn(event.getPlayer());
	}

	/** Cheap backstop for your own character only, in case a pose change wasn't caught above. */
	@Subscribe
	public void onGameTick(GameTick event)
	{
		Player local = client.getLocalPlayer();
		if (local != null)
		{
			learn(local);
		}
	}

	private void readConfig()
	{
		smoothLocal = config.smoothLocalPlayer();
		smoothOthers = config.smoothOtherPlayers();
	}

	private void learn(Player player)
	{
		if (player == null)
		{
			return;
		}

		Set<Integer> target = player == client.getLocalPlayer() ? localPlayerAnims : otherPlayerAnims;
		add(target, player.getAnimation());
		add(target, player.getPoseAnimation());
		add(target, player.getIdlePoseAnimation());
		add(target, player.getIdleRotateLeft());
		add(target, player.getIdleRotateRight());
		add(target, player.getWalkAnimation());
		add(target, player.getWalkRotateLeft());
		add(target, player.getWalkRotateRight());
		add(target, player.getWalkRotate180());
		add(target, player.getRunAnimation());
	}

	private static void add(Set<Integer> set, int animId)
	{
		if (animId != -1 && set.add(animId))
		{
			log.debug("Learned player animation {}", animId);
		}
	}

	private boolean shouldSmooth(int animId)
	{
		if (!smoothLocal && localPlayerAnims.contains(animId))
		{
			return false;
		}
		if (!smoothOthers && otherPlayerAnims.contains(animId))
		{
			return false;
		}
		return isInterpolatable(animId);
	}

	/**
	 * Animations that look broken when smoothed.
	 * Copied from RuneLite's built-in Animation Smoothing plugin; keep in sync with upstream.
	 */
	private static boolean isInterpolatable(int animId)
	{
		switch (animId)
		{
			case AnimationID.DOG_UPDATE_JACKAL_DEFEND:

			case AnimationID.WYRM_WALK:
			case AnimationID.WYRM_READY:
			case AnimationID.WYRM_ATTACK_MELEE:
			case AnimationID.WYRM_ATTACK_MAGIC:

			case AnimationID.GIANT_UPDATE_BASIC_ATTACK:

			case AnimationID.GHOST_UPDATE_NORMAL_READY:
			case AnimationID.GHOST_UPDATE_NORMAL_WALK:

			case AnimationID.ZOMBIE_UPDATE_SIGN_WALK:

			case AnimationID.DUCK_REWORK_UNDERWATER_READY_AND_EXTRA:

			case AnimationID.WILD_CAVE_CHAINMACE_READY:

			case AnimationID.ELEMENTAL_WHEEL_SPIN:
			case AnimationID.BRAIN_MILL_SAIL_ROTATE:
			case AnimationID.FAI_VARROCK_MILLSAIL:
			case AnimationID.DS2_LITHKREN_GENERATOR_WHEEL:
			case AnimationID.WATERWHEEL_CHUTE:

			case AnimationID.HUMAN_SPELLCAST_DEMONBANE:

			case AnimationID.POH_NEXUS:

			case AnimationID.BURGH_BUCKET_DRIP:

			case AnimationID.KEYKEEPER:

			case AnimationID.TOA_SOT_CAST_B:

			case AnimationID.BASILISK_KNIGHT_MELEE:

			case AnimationID.WGS_HEROIC_CLIMB_SUCCESS_TWO:
				return false;

			default:
				return true;
		}
	}
}

package com.selectivesmoothing;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class SelectiveSmoothingPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(SelectiveSmoothingPlugin.class);
		RuneLite.main(args);
	}
}
